import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path
        return self._request_with_retries(url, method='GET')

    def _request_with_retries(self, url: str, method: str = 'GET') -> str:
        # Handle network errors (URLError) - retry once after 1s
        try:
            req = urllib.request.Request(url, method=method)
            response = urllib.request.urlopen(req, timeout=self.timeout)
            body = response.read().decode('utf-8')
            status = response.getcode()
        except urllib.error.HTTPError as e:
            status = e.code
            body = e.read().decode('utf-8') if e.fp else ''
        except urllib.error.URLError as e:
            # Network error - retry once after 1s
            try:
                time.sleep(1)
                req = urllib.request.Request(url, method=method)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                body = response.read().decode('utf-8')
                status = response.getcode()
            except urllib.error.HTTPError as e2:
                status = e2.code
                body = e2.read().decode('utf-8') if e2.fp else ''
                raise ServerError(f"Server error after retry: {status}") from e2
            except urllib.error.URLError as e2:
                raise ConnectionError(f"Connection error after retry") from e2
            except Exception as e2:
                raise ConnectionError(f"Connection error after retry") from e2
            return body
        except Exception as e:
            raise ConnectionError(f"Connection error") from e

        # Handle HTTP status codes
        if status == 429:
            # Rate limit - retry up to 3 times with exponential backoff (0.5s, 1s, 2s)
            backoffs = [0.5, 1.0, 2.0]
            for i, backoff in enumerate(backoffs):
                time.sleep(backoff)
                try:
                    req = urllib.request.Request(url, method=method)
                    response = urllib.request.urlopen(req, timeout=self.timeout)
                    body = response.read().decode('utf-8')
                    status = response.getcode()
                    break
                except urllib.error.HTTPError as e:
                    status = e.code
                    body = e.read().decode('utf-8') if e.fp else ''
                    if status != 429:
                        break
                except urllib.error.URLError:
                    # Network error during retry - treat as connection error
                    raise ConnectionError(f"Connection error during rate limit retry")
                except Exception:
                    raise ConnectionError(f"Connection error during rate limit retry")
            else:
                # All retries exhausted
                raise RateLimitError(f"Rate limit exceeded after 3 retries")
            # After retry, check if we got a non-429 status
            if status == 429:
                raise RateLimitError(f"Rate limit exceeded")
        elif 500 <= status < 600:
            # Server error - retry once after 1s
            time.sleep(1)
            try:
                req = urllib.request.Request(url, method=method)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                body = response.read().decode('utf-8')
                status = response.getcode()
            except urllib.error.HTTPError as e:
                status = e.code
                body = e.read().decode('utf-8') if e.fp else ''
                raise ServerError(f"Server error after retry: {status}") from e
            except urllib.error.URLError:
                raise ConnectionError(f"Connection error during server error retry")
            except Exception:
                raise ConnectionError(f"Connection error during server error retry")
        elif 400 <= status < 500:
            # Client error (except 429) - raise immediately
            raise ClientError(f"Client error: {status}")
        elif status >= 600:
            # Other errors
            raise ServerError(f"Server error: {status}")

        return body
